function DualCourtTraceModule({onBack,setScreen,seedNames}){
  const [names,setNames]=useState(()=>({a:seedNames&&seedNames.playerA?seedNames.playerA:'Player A',b:seedNames&&seedNames.playerB?seedNames.playerB:'Player B'}));
  const [mode,setMode]=useState('rally');
  const [courts,setCourts]=useState(1);
  const [server,setServer]=useState('a');
  const [rallies,setRallies]=useState(()=>dualTraceLoad());
  const [matches,setMatches]=useState(()=>dualMatchesLoad());
  const [active,setActive]=useState('a');
  const [shots,setShots]=useState([]);
  const [cur,setCur]=useState(null);
  const [pending,setPending]=useState(false);
  const [outcome,setOutcome]=useState('');
  const [showLog,setShowLog]=useState(false);
  const [heatOn,setHeatOn]=useState(false);
  const [dotFilter,setDotFilter]=useState('all');
  const [selectedRallyId,setSelectedRallyId]=useState(null);
  const [syncCode,setSyncCode]=useState(()=>getNameSyncCode());
  const [score,setScore]=useState({a:0,b:0});
  const [gameNum,setGameNum]=useState(1);
  const [games,setGames]=useState([]);
  const [winnerPick,setWinnerPick]=useState(null);
  const [railOpen,setRailOpen]=useState(true);
  const [legendOpen,setLegendOpen]=useState(false);
  const drawing=useRef(false);
  const curRef=useRef(null);
  useEffect(()=>{dualTraceSave(rallies);},[rallies]);
  useEffect(()=>{dualMatchesSave(matches);},[matches]);
  useEffect(()=>{const oO=document.body.style.overflow;document.body.style.overflow='hidden';return()=>{document.body.style.overflow=oO;};},[]);
  const stroke={a:'#57b0dd',b:'#2e6e8e'};
  const other=p=>p==='a'?'b':'a';
  function rallyWinner(shotsArr,outcomeVal){
    if(!shotsArr||!shotsArr.length)return null;
    const lastHitter=shotPlayer(shotsArr[shotsArr.length-1]);
    if(outcomeVal==='Winner'||outcomeVal==='Stroke')return lastHitter;
    if(outcomeVal==='Unforced error'||outcomeVal==='Forced error'||outcomeVal==='Out'||outcomeVal==='Tin')return other(lastHitter);
    return null; // Let = replay, no winner, server unchanged
  }
  function adjustScore(p,delta){setScore(s=>({...s,[p]:Math.max(0,s[p]+delta)}));}
  async function pushCourtDisplay(justFinished){
    const gameForPush=justFinished?justFinished.num:gameNum;
    const outcomesForGame={};
    const shotsForGame=[];
    const regularContacts=[];
    const finalContacts=[];
    rallies.filter(r=>r.game===gameForPush).forEach(r=>{
      outcomesForGame[r.outcome]=(outcomesForGame[r.outcome]||0)+1;
      const arr=r.shots||[];
      arr.forEach((s,i)=>{
        const pl=shotPlayer(s);
        shotsForGame.push({player:pl,path:s.path,strike:!!s.strike});
        if(!s.contact)return;
        if(i===arr.length-1)finalContacts.push({pt:s.contact,player:pl,outcome:r.outcome});
        else regularContacts.push({pt:s.contact,player:pl});
      });
    });
    const payload={type:'courtTraceGame',names:{...names},score:justFinished?{a:0,b:0}:{...score},gameNum:justFinished?justFinished.num+1:gameNum,allGames:justFinished?[...games,justFinished]:games,justFinished:justFinished||null,outcomesForGame,heatOn,shotsForGame,regularContacts,finalContacts,shotCount:shotsForGame.length,updatedAt:new Date().toISOString()};
    try{return await writeLivePlayerRoom(getPersistentLiveRoomId(),'courtTraceGame',payload);}catch{return false;}
  }
  function endGame(){const finished={num:gameNum,a:score.a,b:score.b,names:{...names},endedAt:new Date().toISOString()};setGames(prev=>[...prev,finished]);pushCourtDisplay(finished);setGameNum(n=>n+1);setScore({a:0,b:0});setSelectedRallyId(null);}
  function saveMatch(){
    let gList=games;
    if(score.a>0||score.b>0){
      if(!confirm('Game '+gameNum+' is still in progress ('+score.a+'–'+score.b+'). End it and include it in the match before saving?'))return;
      gList=[...games,{num:gameNum,a:score.a,b:score.b,names:{...names},endedAt:new Date().toISOString()}];
    }
    if(!gList.length){return;}
    const winsA=gList.filter(g=>g.a>g.b).length;
    const winsB=gList.filter(g=>g.b>g.a).length;
    const matchRecord={id:Date.now(),names:{...names},games:gList,winsA,winsB,endedAt:new Date().toISOString()};
    setMatches(prev=>[...prev,matchRecord]);
    setRallies([]);setScore({a:0,b:0});setGames([]);setGameNum(1);setSelectedRallyId(null);resetRally(server);
    
  }
  function pickOutcome(o){setOutcome(o);const all=mode==='single'?(cur?[cur]:[]):(cur?[...shots,cur]:shots);setWinnerPick(o==='Let'?null:rallyWinner(all,o));}
  function resetRally(nextServer){const s=nextServer||server;curRef.current=null;setCur(null);setShots([]);setPending(false);setOutcome('');setWinnerPick(null);setActive(s);setServer(s);}
  function pickServer(s){setServer(s);resetRally(s);}
  function ptFromEvent(e){const r=e.currentTarget.getBoundingClientRect();const x=Math.max(0,Math.min(r.width,e.clientX-r.left));const y=Math.max(0,Math.min(r.height,e.clientY-r.top));return {nx:x/r.width,ny:y/r.height};}
  function playerForSurface(surface){return courts===1?active:surface;}
  function canDraw(surface){if(pending)return false;if(courts===1)return true;if(mode==='single')return true;if(shots.length===0)return true;return surface===active;}
  function begin(surface,e){if(!canDraw(surface))return;e.preventDefault();try{e.currentTarget.setPointerCapture(e.pointerId);}catch(err){}drawing.current=true;const player=playerForSurface(surface);if(courts===2&&mode==='rally'&&shots.length===0){setServer(surface);setActive(surface);}const p=ptFromEvent(e);curRef.current={player,path:[p]};setCur({player,path:[p]});}
  function move(surface,e){if(!drawing.current||!curRef.current)return;e.preventDefault();const p=ptFromEvent(e);const path=curRef.current.path;const last=path[path.length-1];if(!last||Math.hypot((p.nx-last.nx)*1347,(p.ny-last.ny)*1743)>4){curRef.current={player:curRef.current.player,path:[...path,p]};setCur({player:curRef.current.player,path:curRef.current.path});}}
  function end(surface,e){if(!drawing.current)return;e.preventDefault();drawing.current=false;try{e.currentTarget.releasePointerCapture(e.pointerId);}catch(err){}const c=curRef.current;
    if(mode==='strike'){if(!c||!c.path.length){curRef.current=null;setCur(null);return;}const p=c.path[0];const shotObj={player:c.player,path:[p,p],contact:p,strike:true,t:Date.now()};setShots(prev=>[...prev,shotObj]);setActive(other(shotObj.player));curRef.current=null;setCur(null);return;}
    if(!c||c.path.length<3){curRef.current=null;setCur(null);return;}const shotObj={...c,t:Date.now()};if(mode==='single'){setActive(shotObj.player);setPending(true);setOutcome('');curRef.current=shotObj;setCur(shotObj);}else{setShots(prev=>[...prev,shotObj]);setActive(other(shotObj.player));curRef.current=null;setCur(null);}}
  function endpointsFor(player){const pts=[];rallies.forEach(r=>{(r.shots||[]).forEach(s=>{if(shotPlayer(s)===player){const e=s.path[s.path.length-1];if(e)pts.push(e);}});});shots.forEach(s=>{if(s.player===player){const e=s.path[s.path.length-1];if(e)pts.push(e);}});return pts;}
  function heatDots(surface){const out=[];const push=(shot)=>{if(shot.strike)return;const e=shot.path&&shot.path[shot.path.length-1];if(!e)return;const pl=other(shotPlayer(shot));if(surface&&pl!==surface)return;out.push({pt:e,player:pl});};rallies.forEach(r=>{if(r.game!==gameNum)return;if(selectedRallyId&&r.id!==selectedRallyId)return;(r.shots||[]).forEach(push);});if(!selectedRallyId)shots.forEach(push);return out;}
  function contactHeatDots(surface){const out=[];const push=(shot,isLast)=>{if(!shot.contact||isLast)return;const pl=shotPlayer(shot);if(surface&&pl!==surface)return;out.push({pt:shot.contact,player:pl});};rallies.forEach(r=>{if(r.game!==gameNum)return;if(selectedRallyId&&r.id!==selectedRallyId)return;const arr=r.shots||[];arr.forEach((s,i)=>push(s,i===arr.length-1));});if(!selectedRallyId)shots.forEach((s,i)=>push(s,false));return out;}
  function finalContactDots(surface){const out=[];rallies.forEach(r=>{if(r.game!==gameNum)return;if(selectedRallyId&&r.id!==selectedRallyId)return;const arr=r.shots||[];if(!arr.length)return;const last=arr[arr.length-1];if(!last.contact)return;const pl=shotPlayer(last);if(surface&&pl!==surface)return;out.push({pt:last.contact,player:pl,outcome:r.outcome});});return out;}
  function savedShotsFor(player){const out=[];rallies.forEach(r=>{if(r.game!==gameNum)return;if(selectedRallyId&&r.id!==selectedRallyId)return;(r.shots||[]).forEach(s=>{if(shotPlayer(s)===player)out.push(s);});});return out;}
  function endRally(){if((mode==='rally'||mode==='strike')&&(shots.length||cur)){setPending(true);setOutcome('');}}
  function save(){if(!outcome)return;if(outcome!=='Let'&&!winnerPick)return;const w=outcome==='Let'?null:winnerPick;if(mode==='single'){if(!cur)return;setRallies(prev=>[...prev,{id:Date.now(),created:new Date().toISOString(),mode,layout:courts,outcome,player:cur.player,winner:w,game:gameNum,names:{...names},shots:[cur]}]);if(w)setScore(s=>({...s,[w]:s[w]+1}));resetRally(w||server);}else{const all=cur?[...shots,cur]:shots;if(!all.length)return;setRallies(prev=>[...prev,{id:Date.now(),created:new Date().toISOString(),mode,layout:courts,server,outcome,winner:w,game:gameNum,names:{...names},shots:all}]);if(w)setScore(s=>({...s,[w]:s[w]+1}));resetRally(w||server);}}
  function cancel(){curRef.current=null;setCur(null);setPending(false);setOutcome('');setWinnerPick(null);}
  function undoShot(){if((mode==='rally'||mode==='strike')&&shots.length){const last=shots[shots.length-1];setShots(prev=>prev.slice(0,-1));setActive(shotPlayer(last));}else{cancel();}}
  function undoRally(){setRallies(prev=>{if(!prev.length)return prev;const last=prev[prev.length-1];if(last.game!==gameNum){return prev;}if(last.winner)setScore(s=>({...s,[last.winner]:Math.max(0,s[last.winner]-1)}));return prev.slice(0,-1);});}
  function clearAll(){if(confirm('Clear all saved court-trace rallies? This also resets the score.')){setRallies([]);setScore({a:0,b:0});setGames([]);setGameNum(1);resetRally(server);}}

  function Surface({surface,overlay,topOverlay,leftOverlay,legend}){
    const single=courts===1;
    const isLive=mode==='rally'&&!pending&&(single||surface===active);
    const showSaved=single?rallies.filter(r=>r.game===gameNum&&(!selectedRallyId||r.id===selectedRallyId)).flatMap(r=>r.shots||[]):savedShotsFor(surface);
    const committed=single?shots:shots.filter(s=>s.player===surface);
    const curShown=cur&&(single||cur.player===surface);
    let contacts=[];
    if(single){contacts=shots.map((s,i)=>({pt:s.path[s.path.length-1],player:other(s.player),last:i===shots.length-1}));}
    else if(mode==='rally'&&shots.length){const last=shots[shots.length-1];if(other(last.player)===surface)contacts=[{pt:last.path[last.path.length-1],player:surface,last:true}];}
    return <div className={single?'':'dctCol'}>
      {!single&&<div className="dctHead"><span className="dctDot" style={{background:stroke[surface]}}></span><input value={names[surface]} onChange={e=>setNames(n=>({...n,[surface]:e.target.value}))}/>{isLive&&<span className="dctActive" style={{background:stroke[surface]}}>tracing</span>}</div>}
      <div className={"dctCourt"+(isLive?' live':'')} onPointerDown={e=>begin(surface,e)} onPointerMove={e=>move(surface,e)} onPointerUp={e=>end(surface,e)} onPointerCancel={e=>end(surface,e)} onContextMenu={e=>e.preventDefault()}>
        <img src={LMC_TRACE_MAP_DATA_URL} alt="court" draggable={false}/>
        <svg viewBox="0 0 1347 1743" preserveAspectRatio="none">
          {!heatOn&&showSaved.filter(s=>!s.strike).map((s,i)=><polyline key={'sv'+i} points={dualPts(s.path)} fill="none" stroke={stroke[shotPlayer(s)]} strokeWidth="6" strokeOpacity="0.16" strokeLinecap="round" strokeLinejoin="round"/>)}
          {!heatOn&&committed.filter(s=>!s.strike).map((s,i)=><polyline key={'c'+i} points={dualPts(s.path)} fill="none" stroke={stroke[s.player]} strokeWidth="8" strokeOpacity="0.75" strokeLinecap="round" strokeLinejoin="round"/>)}
          {heatOn&&heatDots(single?(dotFilter==='all'?null:dotFilter):surface).map((d,i)=><circle key={'h'+i} cx={d.pt.nx*1347} cy={d.pt.ny*1743} r="9" fill={stroke[d.player]} fillOpacity="0.68" stroke="#ffffff" strokeOpacity="0.5" strokeWidth="1.5"/>)}
          {contactHeatDots(single?(dotFilter==='all'?null:dotFilter):surface).map((d,i)=><rect key={'ct'+i} x={d.pt.nx*1347-6} y={d.pt.ny*1743-6} width="12" height="12" fill={stroke[d.player]} fillOpacity="0.55" stroke="#ffffff" strokeOpacity="0.6" strokeWidth="1.3" transform={`rotate(45 ${d.pt.nx*1347} ${d.pt.ny*1743})`}/>)}
          {finalContactDots(single?(dotFilter==='all'?null:dotFilter):surface).map((d,i)=><rect key={'fc'+i} x={d.pt.nx*1347-9} y={d.pt.ny*1743-9} width="18" height="18" fill={OUTCOME_COLORS[d.outcome]||stroke[d.player]} fillOpacity="0.9" stroke="#ffffff" strokeOpacity="0.9" strokeWidth="2" transform={`rotate(45 ${d.pt.nx*1347} ${d.pt.ny*1743})`}/>)}
          {!heatOn&&contacts.map((g,i)=><circle key={'g'+i} cx={g.pt.nx*1347} cy={g.pt.ny*1743} r={g.last?24:16} fill="none" stroke={stroke[g.player]} strokeWidth={g.last?6:4} strokeDasharray={g.last?'0':'6 6'} strokeOpacity={g.last?1:0.7}/>)}
          {!heatOn&&curShown&&<polyline points={dualPts(cur.path)} fill="none" stroke={stroke[cur.player]} strokeWidth="10" strokeLinecap="round" strokeLinejoin="round"/>}
        </svg>
        {topOverlay&&<div className="dctCourtTopOverlay" onPointerDown={e=>e.stopPropagation()} onPointerMove={e=>e.stopPropagation()} onPointerUp={e=>e.stopPropagation()} onPointerCancel={e=>e.stopPropagation()}>{topOverlay}</div>}
        {leftOverlay&&<div className="dctCourtLeftOverlay" onPointerDown={e=>e.stopPropagation()} onPointerMove={e=>e.stopPropagation()} onPointerUp={e=>e.stopPropagation()} onPointerCancel={e=>e.stopPropagation()}>{leftOverlay}</div>}
        {legend&&<div className="dctCourtLegend" onPointerDown={e=>e.stopPropagation()} onPointerMove={e=>e.stopPropagation()} onPointerUp={e=>e.stopPropagation()} onPointerCancel={e=>e.stopPropagation()}>{legend}</div>}
        {overlay&&<div className="dctCourtOverlay" onPointerDown={e=>e.stopPropagation()} onPointerMove={e=>e.stopPropagation()} onPointerUp={e=>e.stopPropagation()} onPointerCancel={e=>e.stopPropagation()}>{overlay}</div>}
      </div>
    </div>;
  }

  const showServerSel = courts===1 || mode==='rally';
  const modeSel=(<><button type="button" className={'dctBtn'+(mode==='single'?' on':'')} onClick={()=>{setMode('single');resetRally(server);}}>Single</button><button type="button" className={'dctBtn'+(mode==='rally'?' on':'')} onClick={()=>{setMode('rally');resetRally(server);}}>Rally</button><button type="button" className={'dctBtn'+(mode==='strike'?' on':'')} onClick={()=>{setMode('strike');resetRally(server);}}>Contact tap</button></>);
  const courtSel=(<><button type="button" className={'dctBtn'+(courts===1?' on':'')} onClick={()=>{setCourts(1);resetRally(server);}}>1 Court</button><button type="button" className={'dctBtn'+(courts===2?' on':'')} onClick={()=>{setCourts(2);resetRally(server);}}>2 Courts</button></>);
  const serverSel=(<><button type="button" className={'dctBtn svrA'+(active==='a'?' on':'')} onClick={()=>pickServer('a')}>{names.a}</button><button type="button" className={'dctBtn svrB'+(active==='b'?' on':'')} onClick={()=>pickServer('b')}>{names.b}</button></>);
  const utilBtns=(<><button type="button" className={'dctBtn'+(heatOn?' on':'')} onClick={()=>setHeatOn(v=>!v)}>Heat {heatOn?'On':'Off'}</button><div className="dctRailLabel">Show shots</div><div style={{display:'flex',gap:'3px'}}><button type="button" className={'dctBtn'+(dotFilter==='all'?' on':'')} style={{flex:1,padding:'6px 3px',fontSize:'.62rem',overflow:'hidden',textOverflow:'ellipsis',whiteSpace:'nowrap'}} onClick={()=>setDotFilter('all')}>All</button><button type="button" className={'dctBtn'+(dotFilter==='a'?' on':'')} style={{flex:1,padding:'6px 3px',fontSize:'.62rem',overflow:'hidden',textOverflow:'ellipsis',whiteSpace:'nowrap'}} onClick={()=>setDotFilter('a')}>{names.a}</button><button type="button" className={'dctBtn'+(dotFilter==='b'?' on':'')} style={{flex:1,padding:'6px 3px',fontSize:'.62rem',overflow:'hidden',textOverflow:'ellipsis',whiteSpace:'nowrap'}} onClick={()=>setDotFilter('b')}>{names.b}</button></div><button type="button" className="dctBtn red" onClick={undoShot}>Undo shot</button><button type="button" className="dctBtn red" onClick={()=>resetRally(server)}>Clear</button><button type="button" className="dctBtn" onClick={()=>setShowLog(v=>!v)}>{showLog?'Hide':'Show'} log</button><button type="button" className="dctBtn" onClick={()=>{const u=buildLivePlayerViewUrl(getPersistentLiveRoomId());let copied=false;try{navigator.clipboard&&navigator.clipboard.writeText(u);copied=true;}catch(err){}const n=rallies.filter(r=>r.game===gameNum).flatMap(r=>r.shots||[]).length;pushCourtDisplay().then(ok=>{if(ok){}else{}});}}>Push + Copy Display Link</button></>);
  const backBtn=(<button type="button" className="dctBtn back" onClick={()=>onBack?onBack():setScreen('home')}>← Menu</button>);
  const nameEditor=(<><div className="dctRailLabel">Players · A = your player</div><input value={names.a} onChange={e=>setNames(n=>({...n,a:e.target.value}))} onPointerDown={e=>e.stopPropagation()} onFocus={e=>e.stopPropagation()} onClick={e=>e.stopPropagation()} autoComplete="off" autoCorrect="off" autoCapitalize="words" spellCheck="false" placeholder="Player A"/><input value={names.b} onChange={e=>setNames(n=>({...n,b:e.target.value}))} onPointerDown={e=>e.stopPropagation()} onFocus={e=>e.stopPropagation()} onClick={e=>e.stopPropagation()} autoComplete="off" autoCorrect="off" autoCapitalize="words" spellCheck="false" placeholder="Player B"/><div className="dctRailLabel">Sync code (same on both devices)</div><input value={syncCode} onChange={e=>{setSyncCode(e.target.value);setNameSyncCode(e.target.value);}} onPointerDown={e=>e.stopPropagation()} onFocus={e=>e.stopPropagation()} onClick={e=>e.stopPropagation()} autoComplete="off" autoCorrect="off" autoCapitalize="none" spellCheck="false" placeholder="e.g. match1"/><div style={{display:'flex',gap:'4px',marginTop:'4px'}}><button type="button" className="dctBtn" style={{flex:1,fontSize:'.65rem',padding:'6px 4px'}} onClick={async()=>{if(!syncCode.trim()){return;}const ok=await pushSharedNames(names.a,names.b);}}>⇧ Push names</button><button type="button" className="dctBtn" style={{flex:1,fontSize:'.65rem',padding:'6px 4px'}} onClick={async()=>{if(!syncCode.trim()){return;}const shared=await pullSharedNames();if(shared&&(shared.playerA||shared.playerB)){setNames({a:shared.playerA||'',b:shared.playerB||''});}else{}}}>⇩ Pull names</button></div></>);
  const rallyBar=(mode==='rally'&&!pending)?(<div className="dctBar"><span>{shots.length} shot{shots.length===1?'':'s'} · next: <b>{names[active]}</b></span><button type="button" className="dctBtn green" onClick={endRally} disabled={!shots.length&&!cur}>End rally</button></div>):null;
  const outcomePanel=pending?(<div className="dctOutcome"><div className="dctLabel">Outcome</div><div className="dctOutGrid">{DUAL_OUTCOMES.map(o=><button type="button" key={o} className={'dctBtn'+(outcome===o?' on':'')} onClick={()=>setOutcome(o)}>{o}</button>)}</div><div className="dctRow2"><button type="button" className="dctBtn green" disabled={!outcome} onClick={save}>Save + New</button><button type="button" className="dctBtn red" onClick={cancel}>Cancel</button></div></div>):null;
  const winnerRow=outcome?(outcome==='Let'?(<div className="dctMuted" style={{textAlign:'center'}}>Let — replay, no winner, server unchanged.</div>):(<div className="dctWinnerRow"><span className="dctLabel" style={{margin:0}}>Who won the rally?</span><div className="dctWinnerBtns"><button type="button" className={'dctBtn svrA'+(winnerPick==='a'?' on':'')} onClick={()=>setWinnerPick('a')}>{names.a}</button><button type="button" className={'dctBtn svrB'+(winnerPick==='b'?' on':'')} onClick={()=>setWinnerPick('b')}>{names.b}</button></div></div>)):null;
  const dock=(<div className="dctDock">{pending?(<div className="dctDockInner"><div className="dctDockOut">{DUAL_OUTCOMES.map(o=><button type="button" key={o} className={'dctBtn'+(outcome===o?' on':'')} onClick={()=>pickOutcome(o)}>{o}</button>)}</div>{winnerRow}<button type="button" className="dctBtn green" disabled={!outcome||(outcome!=='Let'&&!winnerPick)} onClick={save}>Save + New</button><button type="button" className="dctBtn red" onClick={cancel}>Cancel</button></div>):((mode==='rally'||mode==='strike')?(<div className="dctDockInner"><span>{shots.length} shot{shots.length===1?'':'s'} · next: <b>{names[active]}</b></span><button type="button" className="dctBtn green" onClick={endRally} disabled={!shots.length&&!cur}>End rally</button></div>):(<div className="dctDockInner"><span className="dctMuted">Trace the deciding shot, then choose the outcome.</span></div>))}</div>);
  const legendToggle=(<button type="button" className="dctRailToggle" onClick={()=>setLegendOpen(v=>!v)}>{legendOpen?'✕ Hide key':'ⓘ Key'}</button>);
  const legendPanel=legendOpen?(<div className="dctLegend">
      <div className="dctLegendRow"><span className="dctLegendDot" style={{background:stroke.a}}></span>{names.a}</div>
      <div className="dctLegendRow"><span className="dctLegendDot" style={{background:stroke.b}}></span>{names.b}</div>
      <div className="dctLegendRow"><span className="dctLegendDiamond small" style={{background:'#8ea8bd'}}></span>Contact</div>
      <div className="dctLegendRow"><span className="dctLegendDiamond" style={{background:OUTCOME_COLORS['Winner']}}></span>Winner</div>
      <div className="dctLegendRow"><span className="dctLegendDiamond" style={{background:OUTCOME_COLORS['Unforced error']}}></span>Unforced</div>
      <div className="dctLegendRow"><span className="dctLegendDiamond" style={{background:OUTCOME_COLORS['Forced error']}}></span>Forced</div>
      <div className="dctLegendRow"><span className="dctLegendDiamond" style={{background:OUTCOME_COLORS['Tin']}}></span>Tin</div>
      <div className="dctLegendRow"><span className="dctLegendDiamond" style={{background:OUTCOME_COLORS['Out']}}></span>Out</div>
      <div className="dctLegendRow"><span className="dctLegendDiamond" style={{background:OUTCOME_COLORS['Stroke']}}></span>Stroke</div>
      <div className="dctLegendRow"><span className="dctLegendDiamond" style={{background:OUTCOME_COLORS['Let']}}></span>Let</div>
      {heatOn&&<div className="dctLegendRow"><span className="dctLegendCircle"></span>Heat</div>}
    </div>):null;
  const scoreBar=(<div className="dctScoreBar">
    <div className="dctScoreSide"><button type="button" className="dctScoreAdj" onClick={()=>adjustScore('a',-1)}>−</button><div className="dctScoreName">{names.a}</div><div className="dctScoreNum">{score.a}</div><button type="button" className="dctScoreAdj" onClick={()=>adjustScore('a',1)}>+</button></div>
    <div className="dctScoreMid"><span className="dctGameTag">Game {gameNum}</span><button type="button" className="dctBtn" onClick={()=>{if(confirm('Save Game '+gameNum+' — '+names.a+' '+score.a+' : '+score.b+' '+names.b+'? Score resets for a new game.'))endGame();}}>Save + New Game</button><button type="button" className="dctBtn green" onClick={saveMatch}>Save Match</button></div>
    <div className="dctScoreSide"><button type="button" className="dctScoreAdj" onClick={()=>adjustScore('b',-1)}>−</button><div className="dctScoreName">{names.b}</div><div className="dctScoreNum">{score.b}</div><button type="button" className="dctScoreAdj" onClick={()=>adjustScore('b',1)}>+</button></div>
  </div>);
  const matchesCard=matches.length?(<div className="dctCard" style={{display:'block'}}><b>Saved matches</b>{matches.slice().reverse().map(m=><div className="dctLogItem" key={m.id}>{m.names.a} {m.winsA} – {m.winsB} {m.names.b} ({m.games.length} game{m.games.length===1?'':'s'})</div>)}</div>):null;
  const gamesCard=games.length?(<div className="dctCard" style={{display:'block'}}><b>Completed games</b>{games.map((g,i)=><div className="dctLogItem" key={i}>Game {g.num}: {g.names.a} {g.a} – {g.b} {g.names.b}</div>)}</div>):null;
  const gameRallyCount=rallies.filter(r=>r.game===gameNum).length;
  const gameDurations=rallies.filter(r=>r.game===gameNum).map(r=>rallyDuration(r)).filter(d=>d!=null);
  const avgRallyDuration=gameDurations.length?gameDurations.reduce((a,b)=>a+b,0)/gameDurations.length:null;
  const savedCard=(<div className="dctCard"><b>{gameRallyCount}</b> this game · <span className="dctMuted">{rallies.length} total</span>{avgRallyDuration!=null&&<><br/><span className="dctMuted">Avg rally: {avgRallyDuration.toFixed(1)}s</span></>}<button type="button" className="dctBtn red" onClick={undoRally}>Undo last</button><button type="button" className="dctBtn red" onClick={clearAll}>Clear all</button></div>);
  function rallyDuration(r){const arr=r.shots||[];if(arr.length<2)return null;const times=arr.map(s=>s.t).filter(Boolean);if(times.length<2)return null;const secs=(Math.max(...times)-Math.min(...times))/1000;return secs;}
  const logCard=showLog?(<div className="dctCard" style={{display:'block'}}>{selectedRallyId&&<button type="button" className="dctBtn on" style={{width:'100%',marginBottom:'8px'}} onClick={()=>setSelectedRallyId(null)}>✕ Showing 1 rally only — tap to show all</button>}{rallies.slice().reverse().map((r,i)=>{const dur=rallyDuration(r);return <div className="dctLogItem" key={r.id||i} style={{cursor:'pointer',outline:selectedRallyId===r.id?'2px solid #60a5fa':'none'}} onClick={()=>setSelectedRallyId(selectedRallyId===r.id?null:r.id)}><b>G{r.game||1}·Rally {rallies.length-i}</b> · {(r.names?r.names.a:names.a)+' v '+(r.names?r.names.b:names.b)} · {r.mode==='rally'?((r.shots?r.shots.length:0)+' shots'):((r.names?r.names[r.player]:names[r.player])||'—')}{dur!=null?' · '+dur.toFixed(1)+'s':''} · <span className="dctPill">{r.outcome}</span></div>;})}{!rallies.length&&<span className="dctMuted">No saved rallies yet.</span>}</div>):null;
  const railToggle=(<button type="button" className="dctRailToggle" onClick={()=>setRailOpen(v=>!v)}>{railOpen?'✕ Hide menu':'☰ Menu'}</button>);
  const railPanel=railOpen?(<div className="dctRailFloat">
      {backBtn}
      <div className="dctRailLabel">Capture</div>{modeSel}
      <div className="dctRailLabel">Courts</div>{courtSel}
      {nameEditor}
      <div className="dctRailLabel">{mode==='rally'?'Current hitter (tap to override)':'Hitter'}</div>{serverSel}
      <div className="dctRailLabel">Tools</div>{utilBtns}
      {savedCard}
      {gamesCard}
      {matchesCard}
      {logCard}
    </div>):null;

  if(courts===1){
    return <div className="dctPage"><style>{dctCss}</style>
      <div className="dctFullWrap">{Surface({surface:"one",overlay:dock,topOverlay:scoreBar,leftOverlay:<div className="dctRailFloatWrap">{railToggle}{railPanel}</div>,legend:<div className="dctLegendWrap">{legendToggle}{legendPanel}</div>})}</div>
    </div>;
  }
  return <div className="dctPage"><style>{dctCss}</style>
    <div className="dctTop">
      <div className="dctTitle"><h1>Court Trace</h1><p>Rally on two courts — trace a shot; the ring shows where the reply is played from on the other court.</p></div>
      <div className="dctActions">{modeSel}{utilBtns}{backBtn}</div>
    </div>
    <div className="dctSelRow"><span className="dctSelLabel">Courts</span>{courtSel}{showServerSel&&<><span className="dctSelSep"></span><span className="dctSelLabel">{mode==='rally'?'Current hitter':'Hitter'}</span>{serverSel}</>}</div>
    {scoreBar}
    <div className="dctMaps">{Surface({surface:"a"})}{Surface({surface:"b"})}</div>
    <div className="dctSide">{savedCard}{gamesCard}{matchesCard}{logCard}</div>
    {dock}
  </div>;
}

function LiveMatchTraceModule({setScreen}){
  const mapRef=useRef(null);
  const drawRef=useRef(null);
  const heatRef=useRef(null);
  const drawingRef=useRef(false);
  const pointerIdRef=useRef(null);
  const [size,setSize]=useState({w:0,h:0});
  const [path,setPath]=useState([]);
  const pathRef=useRef([]);
  const [rallies,setRallies]=useState(()=>lmcTraceLoad());
  const [pending,setPending]=useState(false);
  const [outcome,setOutcome]=useState('');
  const [heatOn,setHeatOn]=useState(true);
  const [showLog,setShowLog]=useState(false);
  useEffect(()=>{const oldOverflow=document.body.style.overflow;const oldTouch=document.body.style.touchAction;document.body.style.overflow='hidden';document.body.style.touchAction='none';return()=>{document.body.style.overflow=oldOverflow;document.body.style.touchAction=oldTouch;};},[]);
  useEffect(()=>{lmcTraceSave(rallies);},[rallies]);
  useEffect(()=>{const t=setTimeout(()=>{try{writeLivePlayerRoom(getPersistentLiveRoomId(),'matchTrace',{type:'matchTrace',rallies:rallies.slice(-40),path:(path||[]).map(q=>({nx:q.nx,ny:q.ny,time:q.time})),pending,outcome,heatOn,updatedAt:new Date().toISOString()});}catch{}},300);return()=>clearTimeout(t);},[rallies,path,pending,outcome,heatOn]);
  useEffect(()=>{function resize(){const el=mapRef.current;if(!el)return;const r=el.getBoundingClientRect();setSize({w:Math.max(1,r.width),h:Math.max(1,r.height)});}resize();window.addEventListener('resize',resize);window.addEventListener('orientationchange',resize);return()=>{window.removeEventListener('resize',resize);window.removeEventListener('orientationchange',resize);};},[]);
  function setupCanvas(canvas){if(!canvas||!size.w||!size.h)return null;const ratio=window.devicePixelRatio||1;canvas.width=Math.round(size.w*ratio);canvas.height=Math.round(size.h*ratio);canvas.style.width=size.w+'px';canvas.style.height=size.h+'px';const ctx=canvas.getContext('2d');ctx.setTransform(ratio,0,0,ratio,0,0);ctx.clearRect(0,0,size.w,size.h);return ctx;}
  function drawOne(ctx,pts,color,width,alpha){if(!ctx||!pts||pts.length<2)return;ctx.save();ctx.globalAlpha=alpha;ctx.strokeStyle=color;ctx.lineWidth=width;ctx.lineCap='round';ctx.lineJoin='round';ctx.beginPath();ctx.moveTo(pts[0].x,pts[0].y);for(let i=1;i<pts.length;i++)ctx.lineTo(pts[i].x,pts[i].y);ctx.stroke();ctx.restore();}
  useEffect(()=>{const ctx=setupCanvas(heatRef.current);if(!ctx||!heatOn)return;rallies.forEach(r=>{const pts=lmcTraceDenorm(r.path,size.w,size.h);const danger=r.outcome==='Non-functional'||r.outcome==='Intercepted'||r.outcome==='Opponent advantage'||r.outcome==='Error';drawOne(ctx,pts,danger?'#ff2f62':'#159bff',10,0.24);});},[rallies,heatOn,size.w,size.h]);
  useEffect(()=>{const ctx=setupCanvas(drawRef.current);const pts=lmcTraceDenorm(path,size.w,size.h);drawOne(ctx,pts,'#ff2f62',8,0.98);},[path,size.w,size.h]);
  function pointFromEvent(e){const el=mapRef.current;if(!el)return null;const r=el.getBoundingClientRect();const x=Math.max(0,Math.min(r.width,e.clientX-r.left));const y=Math.max(0,Math.min(r.height,e.clientY-r.top));return {nx:x/r.width,ny:y/r.height,time:Date.now()};}
  function beginTrace(e){if(pending)return;e.preventDefault();e.stopPropagation();try{e.currentTarget.setPointerCapture(e.pointerId);pointerIdRef.current=e.pointerId;}catch{}drawingRef.current=true;const p=pointFromEvent(e);pathRef.current=p?[p]:[];setPath(pathRef.current);}
  function moveTrace(e){if(!drawingRef.current)return;e.preventDefault();e.stopPropagation();const p=pointFromEvent(e);if(!p)return;const a=pathRef.current;const last=a[a.length-1];if(!last||Math.hypot((p.nx-last.nx)*size.w,(p.ny-last.ny)*size.h)>3){pathRef.current=[...a,p];setPath(pathRef.current);}}
  function endTrace(e){if(!drawingRef.current)return;e.preventDefault();e.stopPropagation();drawingRef.current=false;try{if(pointerIdRef.current!=null)e.currentTarget.releasePointerCapture(pointerIdRef.current);}catch{}pointerIdRef.current=null;if(pathRef.current.length<6){pathRef.current=[];setPath([]);return;}setPending(true);setOutcome('');}
  function clearCurrent(){drawingRef.current=false;pathRef.current=[];setPath([]);setPending(false);setOutcome('');}
  function saveRally(){if(!outcome||pathRef.current.length<6)return;const p=pathRef.current;const pct=lmcTraceCorridorPct(p);setRallies(prev=>[...prev,{id:Date.now(),created:new Date().toISOString(),outcome,corridorPct:pct,corridor:pct>=18,path:p.map(q=>({nx:q.nx,ny:q.ny,time:q.time}))}]);pathRef.current=[];setPath([]);setPending(false);setOutcome('');}
  function undoLast(){setRallies(prev=>prev.slice(0,-1));}
  function clearAll(){if(confirm('Clear all saved rally traces?')){setRallies([]);clearCurrent();}}
  const corridorCount=rallies.filter(r=>r.corridor).length;
  const corridorRate=rallies.length?Math.round((corridorCount/rallies.length)*100):0;
  const dangerCount=rallies.filter(r=>['Non-functional','Intercepted','Opponent advantage','Error'].includes(r.outcome)).length;
  const currentPct=lmcTraceCorridorPct(pathRef.current);
  const outcomes=rallies.reduce((o,r)=>{o[r.outcome]=(o[r.outcome]||0)+1;return o;},{});
  const topOutcome=Object.entries(outcomes).sort((a,b)=>b[1]-a[1])[0];
  const status=pending?'Trace captured. Choose outcome.':path.length?'Tracing rally… keep finger down until rally ends.':'Ready. Finger down on the map and trace the full rally.';
  return <div className="lmcTracePage">
    <style>{`
.lmcTracePage{position:fixed!important;inset:0!important;z-index:9998!important;background:#061020!important;color:#eaf4fb!important;overflow:hidden!important;touch-action:none!important;font-family:system-ui,-apple-system,Segoe UI,Roboto,Arial,sans-serif;}
.lmcTraceTop{position:absolute;left:0;right:0;top:0;z-index:5;display:flex;align-items:center;justify-content:space-between;gap:8px;padding:10px 12px;background:rgba(6,16,32,.96);border-bottom:1px solid rgba(255,255,255,.14);}
.lmcTraceTitle h1{font-size:18px;line-height:1;margin:0;color:#eaf4fb!important}.lmcTraceTitle p{font-size:12px;margin:3px 0 0;color:#9fb0c2!important}.lmcTraceActions{display:flex;gap:7px;align-items:center;flex-wrap:wrap;justify-content:flex-end}.lmcTraceBtn{appearance:none;-webkit-appearance:none;background:#11243a!important;color:#eaf4fb!important;border:1px solid #2d4766!important;border-radius:999px!important;padding:9px 11px!important;font-weight:800!important;font-size:12px!important;box-shadow:none!important}.lmcTraceBtn.green{background:#0f3a24!important;border-color:#5c9c7a!important}.lmcTraceBtn.red{background:#3a1018!important;border-color:#fb7185!important}.lmcTraceBtn.on{background:#2563eb!important;border-color:#60a5fa!important}.lmcTraceMain{position:absolute;left:0;right:0;top:52px;bottom:0;display:block;padding:6px;overflow:hidden;touch-action:none!important;}
.lmfNameBar{display:grid;grid-template-columns:1fr 1fr;gap:10px;background:#0b1624;border:1px solid #20364f;border-radius:18px;padding:12px;margin-bottom:12px}.lmfNameBar label{color:#9fb3c4;font-size:.76rem;font-weight:900;text-transform:uppercase;letter-spacing:.05em}.lmfNameBar input{display:block;width:100%;margin-top:5px;background:#061020!important;color:#fff!important;border:1px solid #2b4a66!important;border-radius:12px;padding:10px;font-size:1rem;font-weight:850}.lmfSimpleZoneMap{position:relative;display:grid;grid-template-columns:1fr 1fr;grid-template-rows:1fr 1fr;height:360px;max-width:520px;border:4px solid #dfe7f1;border-top-width:8px;border-radius:16px;background:#102238;overflow:hidden;margin:10px 0 12px;box-shadow:inset 0 0 0 1px rgba(255,255,255,.18)}.lmfSimpleZone{position:relative;z-index:2;display:flex;flex-direction:column;align-items:center;justify-content:center;border:1px solid rgba(255,255,255,.26);color:#eaf4fb;font-weight:1000;cursor:pointer;user-select:none}.lmfSimpleZone b{font-size:2.4rem;line-height:1}.lmfSimpleZone span{font-size:.78rem;color:#9fb3c4;margin-top:4px}.lmfSimpleZone.on{background:#2563eb!important}.lmfSimpleCorridorBand{position:absolute;left:41%;right:41%;top:0;bottom:0;z-index:4;display:grid;grid-template-columns:1fr 1fr;grid-template-rows:1fr 1fr;border-left:2px dashed #fb7185;border-right:2px dashed #fb7185;background:rgba(244,63,94,.22)}.lmfSimpleCorridorBand div{display:flex;align-items:center;justify-content:center;border:1px dashed rgba(251,113,133,.6);color:#ffe4e8;font-weight:1000;font-size:.9rem;cursor:pointer}.lmfSimpleCorridorBand div:hover{background:rgba(244,63,94,.38)}.lmfSimpleCourtLine{position:absolute;z-index:1;left:0;right:0;border-top:2px solid rgba(255,255,255,.45)}.lmfSimpleCourtLine.short{top:43%}.lmfSimpleCourtLine.half{top:50%;border-top-style:dashed}.lmfSimpleZone.z1{grid-column:1;grid-row:1}.lmfSimpleZone.z2{grid-column:2;grid-row:1}.lmfSimpleZone.z4{grid-column:1;grid-row:2}.lmfSimpleZone.z3{grid-column:2;grid-row:2}
@media(max-width:820px){.lmcTraceTop{align-items:flex-start}.lmcTraceTitle h1{font-size:16px}.lmcTraceTitle p{display:none}.lmcTraceBtn{font-size:11px;padding:8px 9px!important}}
.lmcTraceMapWrap{position:relative;width:100%;height:100%;min-height:0;background:#fff!important;border:1px solid rgba(255,255,255,.22);border-radius:10px;overflow:hidden;touch-action:none!important;user-select:none!important;-webkit-user-select:none!important;-webkit-touch-callout:none!important;}
.lmcTraceMapWrap img{position:absolute;inset:0;width:100%;height:100%;object-fit:contain;user-select:none!important;-webkit-user-drag:none!important;pointer-events:none!important;background:white!important;}
.lmcTraceCanvas{position:absolute;inset:0;width:100%;height:100%;touch-action:none!important;user-select:none!important;-webkit-user-select:none!important;pointer-events:auto!important;}
.lmcTraceSide{position:absolute;right:14px;top:70px;z-index:6;width:min(300px,calc(100vw - 28px));max-height:calc(100vh - 150px);background:rgba(7,17,31,.88)!important;border:1px solid #20344f;border-radius:16px;padding:10px;overflow:auto;backdrop-filter:blur(8px);}.lmcTraceSide:not(.open){width:auto;max-width:280px}.lmcTraceCard{background:rgba(7,17,31,.78)!important;border:1px solid #21364f;border-radius:14px;padding:8px;margin-bottom:7px}.lmcTraceLabel{font-size:10px;color:#8ea3bd;letter-spacing:.08em;font-weight:950;text-transform:uppercase}.lmcTraceValue{font-size:22px;font-weight:950;color:#fff;margin-top:2px}.lmcTraceSmall{font-size:11px;color:#aab8ca;line-height:1.25}.lmcTraceGrid{display:grid;grid-template-columns:1fr 1fr;gap:7px;margin-top:7px}.lmcOutcome{position:absolute;left:50%;bottom:14px;transform:translateX(-50%);z-index:9;width:min(760px,calc(100vw - 20px));background:rgba(9,18,32,.98)!important;border:1px solid #31486a;border-radius:18px;padding:12px;box-shadow:0 20px 60px rgba(0,0,0,.55);}.lmcOutcomeGrid{display:grid;grid-template-columns:repeat(4,1fr);gap:8px;margin-top:8px}@media(max-width:620px){.lmcOutcomeGrid{grid-template-columns:1fr 1fr}.lmcOutcome{bottom:8px}.lmcTraceSide{top:auto;bottom:12px;right:12px;max-height:34vh;width:min(320px,calc(100vw - 24px))}}.lmcLogItem{border:1px solid #21364f;background:#07111f;border-radius:12px;padding:8px;margin-top:7px;font-size:12px;color:#dce8f5}.lmcPill2{display:inline-block;border:1px solid #3b82f6;background:#10294a;border-radius:999px;padding:3px 7px;margin:3px 4px 0 0;font-weight:800;font-size:11px}.lmcPill2.red{border-color:#fb7185;background:#34101a}.lmcTraceHelp{position:absolute;left:14px;bottom:14px;z-index:4;max-width:520px;background:rgba(6,16,32,.72);border:1px solid rgba(255,255,255,.18);border-radius:14px;padding:8px 10px;color:#d6e3f2;font-size:11px;line-height:1.3;pointer-events:none;}.lmcTraceStatus{font-weight:900;color:#fff}.lmcTraceNoScroll,.lmcTraceNoScroll *{touch-action:none!important;}
`}</style>
    <div className="lmcTraceTop">
      <div className="lmcTraceTitle"><h1>Live Match Coaching · Continuous Trace</h1><p>Trace the full rally. Lift finger to end. Outcome → Save + New Rally.</p></div>
      <div className="lmcTraceActions"><button type="button" className="lmcTraceBtn" onClick={()=>{const u=buildLivePlayerViewUrl(getPersistentLiveRoomId());try{navigator.clipboard&&navigator.clipboard.writeText(u);}catch{}}}>Copy Display</button><button type="button" className="lmcTraceBtn" onClick={()=>setScreen('home')}>Home</button><button type="button" className="lmcTraceBtn red" onClick={undoLast}>Undo Last</button><button type="button" className="lmcTraceBtn red" onClick={clearCurrent}>Clear Trace</button><button type="button" className={'lmcTraceBtn '+(heatOn?'on':'')} onClick={()=>setHeatOn(v=>!v)}>Heat {heatOn?'On':'Off'}</button><button type="button" className="lmcTraceBtn" onClick={()=>setShowLog(v=>!v)}>{showLog?'Hide':'Show'} Log</button></div>
    </div>
    <div className="lmcTraceMain lmcTraceNoScroll">
      <div className="lmcTraceMapWrap" ref={mapRef} onPointerDown={beginTrace} onPointerMove={moveTrace} onPointerUp={endTrace} onPointerCancel={endTrace} onContextMenu={e=>e.preventDefault()}>
        <img src={LMC_TRACE_MAP_DATA_URL} alt="Checkerboard match-analysis mapping court" draggable={false}/>
        <canvas ref={heatRef} className="lmcTraceCanvas" style={{pointerEvents:'none'}}/>
        <canvas ref={drawRef} className="lmcTraceCanvas"/>
        <div className="lmcTraceHelp"><span className="lmcTraceStatus">{status}</span><br/>Central corridor is auto-estimated from the traced path \u2014 the corridor is the marking, the Poached Egg is the meaning: contacts traced outside it are toast contacts. Red heat = danger outcome.</div>
      </div>
      <div className="lmcTraceSide">
        <div className="lmcTraceGrid"><div className="lmcTraceCard"><div className="lmcTraceLabel">Rallies</div><div className="lmcTraceValue">{rallies.length}</div></div><div className="lmcTraceCard"><div className="lmcTraceLabel">Corridor load</div><div className="lmcTraceValue">{corridorRate}%</div></div></div>
        <div className="lmcTraceCard"><div className="lmcTraceLabel">Current trace</div><div className="lmcTraceSmall">{path.length?path.length+' points · corridor estimate '+currentPct+'%':'No active trace.'}</div></div>
        <div className="lmcTraceCard"><div className="lmcTraceLabel">Quick finding</div><div className="lmcTraceSmall">{rallies.length?corridorCount+'/'+rallies.length+' rallies entered the central corridor estimate. '+dangerCount+' danger outcomes logged.': 'No rallies saved yet.'}{topOutcome?' Most common outcome: '+topOutcome[0]+'.':''}</div></div>
        <div className="lmcTraceGrid"><button type="button" className="lmcTraceBtn red" onClick={clearAll}>Clear All</button><button type="button" className="lmcTraceBtn green" onClick={()=>{if(pending&&outcome)saveRally();}}>Save + New</button></div>
        {showLog&&<div className="lmcTraceCard"><div className="lmcTraceLabel">Rally log</div>{rallies.length?rallies.slice().reverse().map((r,i)=><div className="lmcLogItem" key={r.id||i}><strong>Rally {rallies.length-i}</strong><br/><span className={'lmcPill2 '+(['Non-functional','Intercepted','Opponent advantage','Error'].includes(r.outcome)?'red':'')}>{r.outcome}</span><span className="lmcPill2">Corridor {r.corridor?'YES':'NO'}</span><span className="lmcPill2">{r.corridorPct}%</span><div className="lmcTraceSmall">{new Date(r.created).toLocaleTimeString([], {hour:'2-digit',minute:'2-digit'})} · {r.path.length} points</div></div>):<div className="lmcTraceSmall">No saved rallies yet.</div>}</div>}
      </div>
    </div>
    {pending&&<div className="lmcOutcome"><div className="lmcTraceLabel">Rally traced — choose outcome</div><div className="lmcTraceSmall">Corridor estimate {currentPct}%. Then Save + New Rally.</div><div className="lmcOutcomeGrid">{LMC_TRACE_OUTCOMES.map(o=><button key={o} type="button" className={'lmcTraceBtn '+(outcome===o?'on':'')} onClick={()=>setOutcome(o)}>{o}</button>)}</div><div className="lmcTraceGrid"><button type="button" className="lmcTraceBtn green" disabled={!outcome} onClick={saveRally}>Save + New Rally</button><button type="button" className="lmcTraceBtn red" onClick={clearCurrent}>Cancel / Redraw</button></div></div>}
  </div>;
}

/* ───────────────────── APP SHELL ─────────────────────
   Minimal host for the suite. 'home' is the Live Match Coaching menu itself.
   go('home') from inside the suite remounts LiveMatchCoaching (key bump), which
   re-runs its load path — the same forced mode:'menu' reset the main app relied
   on by unmounting the screen. Player-display routing and the waiting/diagnostic
   card mirror main's App(). */
function App(){
  const[liveRoomParam]=useState(()=>getLiveRoomFromUrl());
  const[livePayload,setLivePayload]=useState(null);
  const[liveStatus,setLiveStatus]=useState(liveRoomParam?'Connecting live display…':'');
  const[livePollAttempts,setLivePollAttempts]=useState(0);
  const[screen]=useState(()=>liveRoomParam?'playerDisplay':'home');
  const[homeEpoch,setHomeEpoch]=useState(0);
  useEffect(()=>{
    if(!liveRoomParam) return;
    let cancelled=false;
    async function load(){
      const row=await readLivePlayerRoom(liveRoomParam);
      if(cancelled) return;
      setLivePollAttempts(n=>n+1);
      if(row?.payload){setLivePayload(row.payload);setLiveStatus('Live');}
      else setLiveStatus('Waiting for coach device…');
    }
    load();
    const id=setInterval(load,1200);
    return ()=>{cancelled=true;clearInterval(id);};
  },[liveRoomParam]);
  useEffect(()=>{
    if(screen!=='playerDisplay')return;
    if(!(typeof navigator!=='undefined'&&navigator.wakeLock))return;
    let lock=null;
    async function acquire(){try{if(document.visibilityState==='visible'){lock=await navigator.wakeLock.request('screen');}}catch{}}
    acquire();
    const onVis=()=>{if(document.visibilityState==='visible')acquire();};
    document.addEventListener('visibilitychange',onVis);
    return ()=>{document.removeEventListener('visibilitychange',onVis);try{lock&&lock.release();}catch{}lock=null;};
  },[screen]);
  function go(next){if(next==='home')setHomeEpoch(n=>n+1);}
  if(screen==='playerDisplay'&&livePayload?.type==='matchTrace'){return <MatchTracePlayerDisplay payload={livePayload}/>;}
  if(screen==='playerDisplay'&&livePayload?.type==='courtTraceGame'){return <CourtTraceGamePlayerDisplay payload={livePayload}/>;}
  if(screen==='playerDisplay'&&liveRoomParam&&!livePayload){
    let lastWrite=null,lastError=null;
    try{lastWrite=JSON.parse(localStorage.getItem('checkerboardLiveLastWrite')||'null');}catch{}
    try{lastError=localStorage.getItem('checkerboardLiveLastError');}catch{}
    const stuck=livePollAttempts>=3;
    return <div className="playerDisplayPage"><div className="playerDisplayShell competitionPlayerDisplayShell"><div className="playerDisplayTop"><span>LIVE PLAYER DISPLAY</span><h1>Match Analysis Live</h1><p>{liveStatus}</p>
      {stuck&&<div style={{marginTop:'20px',textAlign:'left',background:'#0b1624',border:'1px solid #20364f',borderRadius:'12px',padding:'14px',fontSize:'.8rem',color:'#9fb3c4',maxWidth:'520px'}}>
        <div style={{color:'#fca5a5',fontWeight:800,marginBottom:'6px'}}>No data arrived after {livePollAttempts} tries — diagnostics:</div>
        <div>Room: {liveRoomParam}</div>
        <div>Last successful write on this device: {lastWrite?`${lastWrite.mode} at ${lastWrite.at}`:'none recorded'}</div>
        {lastError&&<div style={{color:'#fca5a5'}}>Last write error: {lastError}</div>}
        <div style={{marginTop:'8px'}}>If this is a second device, check it's connected to the internet. If it's the same device/browser as the coach tab, try Push again from the coach screen.</div>
      </div>}
    </div></div></div>;
  }
  return <>
    <LiveMatchCoaching key={homeEpoch} setScreen={go}/>
    <div className="versionStamp" title="Deployed build">{APP_VERSION.split(' ')[0]}</div>
  </>;
}

createRoot(document.getElementById('root')).render(<App/>);

